begin;
create schema if not exists voyage_private;
revoke all on schema voyage_private from public,anon,authenticated;
create table voyage_private.settings(singleton boolean primary key default true check(singleton), registration boolean not null default false, community boolean not null default false, terms text not null default 'draft-2026-11-25', privacy text not null default 'draft-2026-11-25', guidelines text not null default 'draft-2026-11-25');
insert into voyage_private.settings default values;
create table voyage_private.staff(id uuid primary key references auth.users on delete cascade);
create table voyage_private.audit(id bigint generated always as identity primary key, actor uuid, action text not null, subject text, at timestamptz default now());
create table public.v26_profiles(id uuid primary key references auth.users on delete cascade, username text unique not null check(username ~ '^[a-z0-9_]{3,28}$'), suspended boolean not null default false, created_at timestamptz not null default now());
create table public.v26_acceptance(id uuid not null references auth.users on delete cascade, terms text not null, privacy text not null, guidelines text not null, at timestamptz not null default now(), primary key(id,terms,privacy,guidelines));
create table public.v26_records(id uuid primary key default gen_random_uuid(), owner uuid not null default auth.uid() references auth.users on delete cascade, kind text not null check(kind in ('visit','trip','journal','settings')), data jsonb not null check(jsonb_typeof(data)='object' and octet_length(data::text)<55000), created_at timestamptz not null default now());
create index on public.v26_records(owner,kind,created_at desc);
create table public.v26_posts(id uuid primary key default gen_random_uuid(), owner uuid not null references auth.users on delete cascade, kind text not null check(kind in ('review','story','discussion')), destination text not null check(length(destination)<=200), title text not null check(length(title) between 1 and 200), body text not null check(length(body) between 10 and 8000), scores jsonb not null default '{}', status text not null default 'pending' check(status in ('pending','published','removed')), created_at timestamptz not null default now());
create unique index on public.v26_posts(owner,lower(destination)) where kind='review';
create index on public.v26_posts(status,kind,destination);
create table public.v26_reports(id uuid primary key default gen_random_uuid(), owner uuid references auth.users on delete set null, post uuid references public.v26_posts on delete set null, reason text not null check(length(reason) between 8 and 1500), status text default 'open',created_at timestamptz default now());
alter table public.v26_profiles enable row level security;
alter table public.v26_acceptance enable row level security;
alter table public.v26_records enable row level security;
alter table public.v26_posts enable row level security;
alter table public.v26_reports enable row level security;
revoke all on public.v26_profiles,public.v26_acceptance,public.v26_records,public.v26_posts,public.v26_reports from public,anon,authenticated;
create function public.v26_active() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.v26_profiles p join public.v26_acceptance a using(id) cross join voyage_private.settings s where p.id=auth.uid() and not p.suspended and (a.terms,a.privacy,a.guidelines)=(s.terms,s.privacy,s.guidelines)) $$;
create function public.v26_state() returns jsonb language sql stable security definer set search_path='' as $$ select jsonb_build_object('registration',s.registration,'community',s.community,'terms',s.terms,'privacy',s.privacy,'guidelines',s.guidelines,'active',public.v26_active(),'staff',exists(select 1 from voyage_private.staff join public.v26_profiles using(id) where id=auth.uid() and not suspended),'username',(select username from public.v26_profiles where id=auth.uid())) from voyage_private.settings s $$;
create function voyage_private.guard_signup() returns trigger language plpgsql security definer set search_path='' as $$ begin if not (select registration from voyage_private.settings) then raise exception 'Public registration is closed'; end if;return new;end $$;
create trigger v26_signup_gate before insert on auth.users for each row execute function voyage_private.guard_signup();
create function public.v26_activate(handle text, adult boolean, terms_version text, privacy_version text, guidelines_version text) returns void language plpgsql security definer set search_path='' as $$ declare s voyage_private.settings; begin select * into s from voyage_private.settings; if auth.uid() is null or adult is not true or (terms_version,privacy_version,guidelines_version) is distinct from (s.terms,s.privacy,s.guidelines) then raise exception 'Current agreements and age confirmation required';end if;
if not exists(select 1 from auth.users where id=auth.uid() and email_confirmed_at is not null) then raise exception 'Verify your email first'; end if;
if not s.registration and not exists(select 1 from public.v26_profiles where id=auth.uid()) then raise exception 'Registration closed';end if;
insert into public.v26_profiles(id,username) values(auth.uid(),lower(trim(handle))) on conflict(id) do nothing;
insert into public.v26_acceptance(id,terms,privacy,guidelines) values(auth.uid(),s.terms,s.privacy,s.guidelines) on conflict do nothing;end $$;
create policy private_reads on public.v26_records for select to authenticated using(owner=(select auth.uid()) and (select public.v26_active()));
create policy private_writes on public.v26_records for insert to authenticated with check(owner=(select auth.uid()) and (select public.v26_active()));
create policy private_updates on public.v26_records for update to authenticated using(owner=(select auth.uid()) and (select public.v26_active())) with check(owner=(select auth.uid()) and (select public.v26_active()));
create policy private_deletes on public.v26_records for delete to authenticated using(owner=(select auth.uid()) and (select public.v26_active()));
grant select,delete on public.v26_records to authenticated;
grant insert(kind,data),update(data) on public.v26_records to authenticated;
create function voyage_private.quota() returns trigger language plpgsql security definer set search_path='' as $$ begin perform pg_advisory_xact_lock(hashtextextended(new.owner::text,0));if (select count(*) from public.v26_records where owner=new.owner)>=2000 then raise exception 'Personal record quota reached';end if;return new;end $$;
create trigger v26_quota before insert on public.v26_records for each row execute function voyage_private.quota();
create function public.v26_publish(post_kind text, place_name text, heading text, content text, ratings jsonb, rights boolean) returns void language plpgsql security definer set search_path='' as $$ begin
if not public.v26_active() or rights is not true or not(select community from voyage_private.settings) then raise exception 'Publishing unavailable';end if;
perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,0));
if (select count(*) from public.v26_posts where owner=auth.uid() and created_at>now()-interval '24 hours')>=5 then raise exception 'Daily submission limit reached';end if;
if post_kind='review' and (nullif(trim(place_name),'') is null or not ratings ? 'Overall experience' or jsonb_typeof(ratings)<>'object' or exists(select 1 from jsonb_each(ratings) e where e.key <> all(array['Overall experience','Natural beauty','Cleanliness','Perceived personal safety','Affordability','Hospitality','Food','Public transportation','Accessibility','Family friendliness','Cultural experience','Tourist infrastructure','Entertainment','Value for money']) or e.value::text !~ '^[1-5]$')) then raise exception 'Invalid rating';end if;
insert into public.v26_posts(owner,kind,destination,title,body,scores) values(auth.uid(),post_kind,trim(place_name),trim(heading),trim(content),ratings);end $$;
create function public.v26_feed(filter_kind text default '', place_name text default '', page_no int default 0) returns table(id uuid,kind text, destination text,title text,body text,scores jsonb,username text,created_at timestamptz) language sql stable security definer set search_path='' as $$ select f.id,f.kind,f.destination,f.title,f.body,f.scores,p.username,f.created_at from public.v26_posts f join public.v26_profiles p on p.id=f.owner where (select community from voyage_private.settings) and not p.suspended and f.status='published' and (filter_kind='' or f.kind=filter_kind) and (place_name='' or lower(f.destination)=lower(place_name)) order by f.created_at desc,f.id limit 25 offset greatest(0,least(page_no,10000))*25 $$;
create function public.v26_rankings() returns table(destination text,reviews bigint,average numeric) language sql stable security definer set search_path='' as $$ select (array_agg(f.destination order by f.created_at,f.id))[1],count(*),round(avg((f.scores->>'Overall experience')::integer),2) from public.v26_posts f join public.v26_profiles p on p.id=f.owner where f.kind='review' and f.status='published' and not p.suspended and (select community from voyage_private.settings) group by lower(f.destination) having count(*)>=5 order by 3 desc,2 desc,1 limit 100 $$;
create function public.v26_report(post_id uuid,details text) returns void language plpgsql security definer set search_path='' as $$ begin if not public.v26_active() then raise exception 'Active account required';end if;perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,0));if (select count(*) from public.v26_reports where owner=auth.uid() and created_at>now()-interval '1 day')>=5 then raise exception 'Daily report limit reached';end if;insert into public.v26_reports(owner,post,reason) values(auth.uid(),post_id,details);end $$;
create function public.v26_admin() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin if not exists(select 1 from voyage_private.staff join public.v26_profiles using(id) where id=auth.uid() and not suspended) then raise exception 'Administrator required';end if;return jsonb_build_object('users',(select count(*) from public.v26_profiles),'posts',(select count(*) from public.v26_posts),'databaseBytes',pg_database_size(current_database()),'settings',(select to_jsonb(s) from voyage_private.settings s),'pending',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from (select * from public.v26_posts where status='pending' order by created_at limit 50)x),'reports',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from (select * from public.v26_reports where status='open' order by created_at limit 50)x),'audit',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from (select * from voyage_private.audit order by at desc limit 30)x));end $$;
create function public.v26_moderate(op text,target uuid default null) returns void language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from voyage_private.staff join public.v26_profiles using(id) where id=auth.uid() and not suspended) then raise exception 'Administrator required';end if;
case op when 'approve' then update public.v26_posts set status='published' where id=target;when 'remove' then update public.v26_posts set status='removed' where id=target;when 'close report' then update public.v26_reports set status='closed' where id=target;when 'suspend' then update public.v26_profiles set suspended=true where id=target;when 'close registration' then update voyage_private.settings set registration=false;when 'pause community' then update voyage_private.settings set community=false;else raise exception 'Invalid action';end case;
insert into voyage_private.audit(actor,action,subject) values(auth.uid(),op,target::text);end $$;
create function public.v26_delete_account(confirmation text) returns void language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null or confirmation is distinct from 'DELETE' then raise exception 'Confirmation required';end if;delete from auth.users where id=auth.uid();end $$;
do $$ declare fn regprocedure;begin for fn in select oid::regprocedure from pg_proc where pronamespace='public'::regnamespace and proname like 'v26_%' loop execute format('revoke all on function %s from public,anon,authenticated',fn);execute format('grant execute on function %s to authenticated',fn);end loop;end $$;
grant execute on function public.v26_state(),public.v26_feed(text,text,int),public.v26_rankings() to anon;
commit;
